using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;
namespace PZ3D {static class SnapshotLongPathJavaProbe {
 static void Copy(string source,string destination){SnapshotFileSystem.Directories.CreateDirectory(Path.GetDirectoryName(destination));using(var from=new SnapshotFileSystem.Stream(source,FileMode.Open,FileAccess.Read,FileShare.Read))using(var to=new SnapshotFileSystem.Stream(destination,FileMode.CreateNew,FileAccess.Write,FileShare.None)){from.CopyTo(to);to.Flush(true);}}
 static string Hash(string path){using(var sha=System.Security.Cryptography.SHA256.Create())using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))return BitConverter.ToString(sha.ComputeHash(stream));}
 public static int Main(string[] args){LauncherRuntime.Initialize();string root=null;try{
  string source=Path.GetFullPath(args[0]),agent=Path.GetFullPath(args[1]);root=Path.Combine(Path.GetTempPath(),"ozl-longjava-"+Guid.NewGuid().ToString("N"));string game=Path.Combine(root,"用户选择的快照目录-"+new string('a',75),"game"),home=Path.Combine(root,"runtime","home"),sourceJre=Path.Combine(source,"jre64"),jar=Path.Combine(source,"projectzomboid.jar"),java=Path.Combine(sourceJre,"bin","java.exe");string beforeJar=Hash(jar),beforeJava=Hash(java);
  foreach(string directory in Directory.GetDirectories(sourceJre,"*",SearchOption.AllDirectories))SnapshotFileSystem.Directories.CreateDirectory(Path.Combine(game,"jre64",directory.Substring(sourceJre.Length+1)));
  foreach(string file in Directory.GetFiles(sourceJre,"*",SearchOption.AllDirectories))Copy(file,Path.Combine(game,"jre64",file.Substring(sourceJre.Length+1)));Copy(jar,Path.Combine(game,"projectzomboid.jar"));string copiedAgent=Path.Combine(game,"OrangeLauncherRuntime","environment","OrangeEnvironment.jar");Copy(agent,copiedAgent);SnapshotFileSystem.Directories.CreateDirectory(home);
  Console.WriteLine("Actual copied JRE path length="+Path.Combine(game,"jre64","bin","java.exe").Length+"; game="+game);
  try{typeof(SaveEnvironmentRuntime).GetMethods(BindingFlags.Static|BindingFlags.NonPublic).Single(method=>method.Name=="Probe"&&method.GetParameters().Length==4).Invoke(null,new object[]{game,home,copiedAgent,CancellationToken.None});}catch(TargetInvocationException error){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(error.InnerException).Throw();throw;}
  string payload=Path.Combine(game,"media",new string('b',100),new string('c',100),"payload.txt");SnapshotFileSystem.Directories.CreateDirectory(Path.GetDirectoryName(payload));SnapshotFileSystem.Files.WriteAllBytes(payload,System.Text.Encoding.UTF8.GetBytes("copied long-path payload"));string probeClasses=Path.Combine(game,"private-probe"),classes=Path.GetFullPath(args[2]);foreach(string file in Directory.GetFiles(classes,"*",SearchOption.AllDirectories))Copy(file,Path.Combine(probeClasses,file.Substring(classes.Length+1)));
  var start=new System.Diagnostics.ProcessStartInfo(Path.Combine(game,"jre64","bin","java.exe"),"-Djava.awt.headless=true -cp \""+probeClasses+"\" ozl.environment.tests.ActualLongPathIoProbe \""+game+"\" \""+payload+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=game,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=System.Diagnostics.Process.Start(start)){if(!process.WaitForExit(15000)){process.Kill();throw new IOException("Long child JVM read probe timed out");}string output=process.StandardOutput.ReadToEnd(),error=process.StandardError.ReadToEnd();Console.Write(output);if(process.ExitCode!=0||!output.StartsWith("PASS "))throw new IOException("Actual JVM long-child read failed: "+error);}
  if(Hash(jar)!=beforeJar||Hash(java)!=beforeJava)throw new IOException("Installed JRE or game JAR changed during read-only copy/probe");Console.WriteLine("PASS actual copied JRE launched through production Probe and read a child beyond MAX_PATH; source JRE/JAR hashes unchanged; no UI/game entry point");return 0;
 }catch(Exception error){Console.WriteLine(error);return 1;}finally{if(root!=null){string full=Path.GetFullPath(root);if(!full.StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(full).StartsWith("ozl-longjava-",StringComparison.Ordinal))throw new IOException("Unsafe long Java fixture cleanup");if(SnapshotFileSystem.Directories.Exists(full))SnapshotFileSystem.Directories.Delete(full,true);}}}
}}
